import logging _logger = logging.getLogger(__name__)
token_managers = model.search([('active', '=', True)]) _logger.info("Zalo Shared Token cron: checking %s active token managers", len(token_managers))
for token_manager in token_managers: try: if token_manager._is_token_expired(): _logger.info("Zalo Shared Token cron: token expired for %s (ID: %s), refreshing...", token_manager.name, token_manager.id) token_manager.refresh_access_token() _logger.info("Zalo Shared Token cron: token refreshed successfully for %s", token_manager.name) else: _logger.debug("Zalo Shared Token cron: token still valid for %s (ID: %s)", token_manager.name, token_manager.id) except Exception as e: _logger.exception("Zalo Shared Token cron: error refreshing token for %s (ID: %s): %s", token_manager.name, token_manager.id, e)
